   /* CdlstalledpatternOpenAndFill anchored at startIdx — the composed-open fusion seam. */
   internal CdlstalledpatternStream CdlstalledpatternOpenAndFillInternal( ReadOnlySpan<double> inOpen, ReadOnlySpan<double> inHigh, ReadOnlySpan<double> inLow, ReadOnlySpan<double> inClose, int startIdx, out int outBegIdx, out int outNBElement, Span<int> outInteger )
   {
      CdlstalledpatternStream sp = new CdlstalledpatternStream(this);
      RetCode retCode = CdlstalledpatternOpenImpl(sp, inOpen, inHigh, inLow, inClose, startIdx, out outBegIdx, out outNBElement, outInteger, 1);
      sp.outRangeBegIdx = outBegIdx;
      sp.outRangeCount = outNBElement;
      if( retCode == RetCode.Success ) {
         return sp;
      }
      throw StreamFailure("CDLSTALLEDPATTERN", "openAndFill", retCode);
   }

   /* Internal startIdx-anchored open behind CdlstalledpatternOpen (composition seam). */
   internal CdlstalledpatternStream CdlstalledpatternOpenInternal( ReadOnlySpan<double> inOpen, ReadOnlySpan<double> inHigh, ReadOnlySpan<double> inLow, ReadOnlySpan<double> inClose, int startIdx )
   {
      CdlstalledpatternStream sp = new CdlstalledpatternStream(this);
      int[] sink_outInteger = new int[1];
      RetCode retCode = CdlstalledpatternOpenImpl(sp, inOpen, inHigh, inLow, inClose, startIdx, out int outBegIdx, out int outNBElement, sink_outInteger, 0);
      sp.outRangeBegIdx = outBegIdx;
      sp.outRangeCount = outNBElement;
      if( retCode == RetCode.Success ) {
         return sp;
      }
      throw StreamFailure("CDLSTALLEDPATTERN", "open", retCode);
   }

   /// <summary>Open a live <c>CDLSTALLEDPATTERN</c> stream over the warm-up history.</summary>
   /// <remarks>
   /// <para>The handle's <see cref="CdlstalledpatternStream.Value"/> starts at the
   /// last history bar's value — bit-identical to what <c>CDLSTALLEDPATTERN</c>
   /// reports for that bar.</para>
   /// <para>The history must hold at least <c>CDLSTALLEDPATTERN_Lookback(...) + 1</c>
   /// bars (unstable-period aware). Nothing is written to any caller array; use
   /// <c>CdlstalledpatternOpenAndFill</c> to get the warm-up values as well.</para>
   /// </remarks>
   /// <param name="inOpen">Open price of each bar. The warm-up history, oldest bar first.</param>
   /// <param name="inHigh">High price of each bar. The warm-up history, oldest bar first.</param>
   /// <param name="inLow">Low price of each bar. The warm-up history, oldest bar first.</param>
   /// <param name="inClose">Close price of each bar. The warm-up history, oldest bar first.</param>
   /// <returns>The open stream handle.</returns>
   /// <exception cref="InsufficientHistoryException">The history holds fewer than <c>CDLSTALLEDPATTERN_Lookback(...) + 1</c>
   /// bars.</exception>
   /// <exception cref="System.ArgumentException">An optional parameter is outside its documented range, or the input series
   /// have different lengths.</exception>
   /// <exception cref="System.ArgumentOutOfRangeException">The history is empty — which is what a null array becomes, since a span
   /// cannot be null — or it is longer than <see cref="Core.MAX_INDEX"/> + 1,
   /// the two index faults an opener can have (rules S1 and S2).</exception>
   public CdlstalledpatternStream CdlstalledpatternOpen( ReadOnlySpan<double> inOpen, ReadOnlySpan<double> inHigh, ReadOnlySpan<double> inLow, ReadOnlySpan<double> inClose )
   {
      if( inOpen.IsEmpty ) throw new TaLibArgumentOutOfRangeException(nameof(inOpen), "CDLSTALLEDPATTERN open: history is empty", RetCode.OutOfRangeStartIndex);
      if( inOpen.Length > MAX_INDEX + 1 ) throw new TaLibArgumentOutOfRangeException(nameof(inOpen), "CDLSTALLEDPATTERN open: history is longer than MAX_INDEX + 1", RetCode.OutOfRangeEndIndex);
      if( inHigh.IsEmpty ) throw new TaLibArgumentException("CDLSTALLEDPATTERN open: inHigh is empty", nameof(inHigh), RetCode.BadParam);
      if( inLow.IsEmpty ) throw new TaLibArgumentException("CDLSTALLEDPATTERN open: inLow is empty", nameof(inLow), RetCode.BadParam);
      if( inClose.IsEmpty ) throw new TaLibArgumentException("CDLSTALLEDPATTERN open: inClose is empty", nameof(inClose), RetCode.BadParam);
      RequireHistoryLength("CDLSTALLEDPATTERN", "open", "inHigh", inHigh.Length, inOpen.Length);
      RequireHistoryLength("CDLSTALLEDPATTERN", "open", "inLow", inLow.Length, inOpen.Length);
      RequireHistoryLength("CDLSTALLEDPATTERN", "open", "inClose", inClose.Length, inOpen.Length);
      return CdlstalledpatternOpenInternal(inOpen, inHigh, inLow, inClose, 0);
   }

   /// <summary><c>CdlstalledpatternOpen</c> that also fills the output array(s) over the
   /// whole history in the same single pass.</summary>
   /// <remarks>
   /// <para>The values written are bit-identical to what <c>CDLSTALLEDPATTERN</c>
   /// produces over the same series, so no separate batch call is needed for the
   /// warm-up plot.</para>
   /// <para>Output arrays must hold <c>historyLen -
   /// CDLSTALLEDPATTERN_Lookback(...)</c> values and must not alias the inputs
   /// or each other — this path writes the outputs and then reads the input tail
   /// to seed its rings, so the batch tier's in-place allowance does not carry
   /// over here. Both are checked before anything is written, so an undersized
   /// span is an <c>ArgumentException</c> naming it rather than a fault from
   /// inside the fill.</para>
   /// <para>The range written is reported on the returned handle:
   /// <see cref="CdlstalledpatternStream.OutRange"/>.</para>
   /// </remarks>
   /// <param name="inOpen">Open price of each bar. The warm-up history, oldest bar first.</param>
   /// <param name="inHigh">High price of each bar. The warm-up history, oldest bar first.</param>
   /// <param name="inLow">Low price of each bar. The warm-up history, oldest bar first.</param>
   /// <param name="inClose">Close price of each bar. The warm-up history, oldest bar first.</param>
   /// <param name="outInteger">-100 when the pattern is detected (always bearish), 0 otherwise. Never
   /// emits +100. Must hold at least <c>historyLen -
   /// CDLSTALLEDPATTERN_Lookback(...)</c> values.</param>
   /// <returns>The open stream handle, with its fill range set.</returns>
   /// <exception cref="InsufficientHistoryException">The history holds fewer than <c>CDLSTALLEDPATTERN_Lookback(...) + 1</c>
   /// bars.</exception>
   /// <exception cref="System.ArgumentException">An optional parameter is outside its documented range, the input series
   /// have different lengths, an output is shorter than the values the fill
   /// writes, or an output array aliases an input or another output.</exception>
   /// <exception cref="System.ArgumentOutOfRangeException">The history is empty — which is what a null array becomes, since a span
   /// cannot be null — or it is longer than <see cref="Core.MAX_INDEX"/> + 1,
   /// the two index faults an opener can have (rules S1 and S2).</exception>
   public CdlstalledpatternStream CdlstalledpatternOpenAndFill( ReadOnlySpan<double> inOpen, ReadOnlySpan<double> inHigh, ReadOnlySpan<double> inLow, ReadOnlySpan<double> inClose, Span<int> outInteger )
   {
      if( inOpen.IsEmpty ) throw new TaLibArgumentOutOfRangeException(nameof(inOpen), "CDLSTALLEDPATTERN openAndFill: history is empty", RetCode.OutOfRangeStartIndex);
      if( inOpen.Length > MAX_INDEX + 1 ) throw new TaLibArgumentOutOfRangeException(nameof(inOpen), "CDLSTALLEDPATTERN openAndFill: history is longer than MAX_INDEX + 1", RetCode.OutOfRangeEndIndex);
      if( inHigh.IsEmpty ) throw new TaLibArgumentException("CDLSTALLEDPATTERN openAndFill: inHigh is empty", nameof(inHigh), RetCode.BadParam);
      if( inLow.IsEmpty ) throw new TaLibArgumentException("CDLSTALLEDPATTERN openAndFill: inLow is empty", nameof(inLow), RetCode.BadParam);
      if( inClose.IsEmpty ) throw new TaLibArgumentException("CDLSTALLEDPATTERN openAndFill: inClose is empty", nameof(inClose), RetCode.BadParam);
      int guardOutLen = OpenFillCount("CDLSTALLEDPATTERN", "openAndFill", inOpen.Length, CDLSTALLEDPATTERN_Lookback());
      RequireHistoryLength("CDLSTALLEDPATTERN", "openAndFill", "inHigh", inHigh.Length, inOpen.Length);
      RequireHistoryLength("CDLSTALLEDPATTERN", "openAndFill", "inLow", inLow.Length, inOpen.Length);
      RequireHistoryLength("CDLSTALLEDPATTERN", "openAndFill", "inClose", inClose.Length, inOpen.Length);
      RequireFillLength("CDLSTALLEDPATTERN", "openAndFill", "outInteger", outInteger.Length, guardOutLen);
      return CdlstalledpatternOpenAndFillInternal(inOpen, inHigh, inLow, inClose, 0, out _, out _, outInteger);
   }
